#!/usr/bin/env bash
# Regenerates the generated-and-committed data contract from its source of truth
# and fails if a committed copy is stale.
#
# The TS bindings (packages/run-record/src/ and packages/asset-contract/src/, two
# packages because only the latter may be seeded into a run) and the JSON Schemas
# (schema/) are generated by crates/contract-codegen from the Rust types in
# crates/contracts that derive `ts_rs::TS` + `schemars::JsonSchema` (see
# scripts/gen-contract.mjs). Any change to one of those types, the rustdoc
# included, which is emitted into the schemas as descriptions, that is not
# regenerated and committed turns this check red, so the Rust, TypeScript and
# JSON Schema representations of the contract can never silently drift apart.
#
# The artifacts are committed because their readers cannot run the generator:
# they are TypeScript builds of the packages and their consumers, and a static
# docs site serving the schemas as files, none of which can invoke a Rust binary.
set -euo pipefail

log() {
	printf '\n\033[1;34m==> %s\033[0m\n' "$*"
}

# The repository root, two levels above this script, whatever directory the
# caller runs it from.
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

readonly GENERATED=(packages/run-record/src packages/asset-contract/src schema)

log "regenerate the contract (cargo run -p contract-codegen + prettier)"
npm run gen:contract

log "check for drift"
# `git diff` sees a committed file that changed, but not a file the generator
# emits that was never committed: a module or schema added to the generator and
# not to the tree. That is drift too, so an untracked file under the generated
# directories fails.
untracked="$(git ls-files --others --exclude-standard -- "${GENERATED[@]}")"
if [[ -n "$untracked" ]]; then
	printf '%s\n' "$untracked" >&2
	cat >&2 <<'MSG'

error: the generator emitted files that are not committed (listed above).
Run `npm run gen:contract` and commit the result.
MSG
	exit 1
fi
if ! git diff --exit-code -- "${GENERATED[@]}"; then
	cat >&2 <<'MSG'

error: the generated contract artifacts are out of date.
The TypeScript bindings and/or JSON Schemas no longer match the Rust types they
are generated from, so the Rust, TypeScript and JSON Schema representations of
the contract disagree.
Run `npm run gen:contract` and commit the result.
MSG
	exit 1
fi
